registerRefData('nsw-cond-n-581',{"id":581,"pan":null,"ref":"DA-2022/714","address":"37-39 Burelli Street Wollongong 2500","description":"Mixed Use Development","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2024-10-18","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSTH-253!20241018T043748.150 GMT","sha256":"685b5f42e1ae19a4e9dcf4c1e587a4079af04505b3b48a068aea0324df13233d","pages":43,"layout":"numbered","n":20,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/581.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/mixed-use-development-245","lga":"WOLLONGONG","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSSTH-253 - Wollongong City Council - DA-2022/714","stage":"general","stage_basis":"heading","page":7},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT Mixed Use Development - demolition of existing structures and","text":"construction of 14 storey building, two (2) commercial spaces, 71\nresidential apartments, basement and podium sleeved parking, associated\ncommunal open space and landscaping","stage":"general","stage_basis":"heading","page":7},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 37-39 Burelli Street, Wollongong 2500","text":"","stage":"general","stage_basis":"heading","page":7},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Applicant: ADM Projects Australia Pty Ltd","text":"Owner: Burelli Investment Holdings Pty Ltd","stage":"general","stage_basis":"heading","page":7},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $30 million","stage":"general","stage_basis":"heading","page":7},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Building and Sustainability\nIndex: BASIX) 2004\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021\no SEPP No. 65 (Design Quality of Residential Apartment\nDevelopment)\no Wollongong Local Environmental Plan 2009\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Wollongong Development Control Plan 2009\n• Other policies:\no Wollongong City Wide Development Contributions Plan (2023)\no Wollongong Community Participation Plan 2019\n• Planning agreements: Nil\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and\neconomic impacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental\nPlanning and Assessment Act 1979 or regulations\n• Public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":7},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 1 May 2024\n• Clause 4.6 request - departure from clause 8.6 (Building Separation)\n• List any council memo or supplementary report received: 23\nSeptember 2024\n• Written submissions during public exhibition: 2\n• Total number of unique submissions received by way of objection: 2","stage":"general","stage_basis":"heading","page":7},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Briefing: 25 July 2023\no Panel members: Chris Wilson, David Brown, Juliet Grant\no Council assessment staff: Anne Starr, Mark Adamson, Amanda\nKostovski\no Applicant representatives: Angelo Di Martino (ADM Architects),\nPeter Taranto & Daniel Hodge (representing client group -\nEsplanade Wollongong), Luke Rollinson (MMJ Planning), Cartia\nTaranto\no DPE representatives: Amanda Moylan, Tim Mahoney\n• Site inspection: 25 July 2023\no Panel members: Chris Wilson\n• Site inspection: 30 August 2023\no Panel members: Grant Christmas, Juliet Grant, Mark Carlon\n• Status Update Briefing: 6 December 2023\no Panel members: Juliet Grant (A/Chair), Grant Christmas, David\nBrown\no Council assessment staff: Anne Starr, Mark Adamson, Amanda\nKostovski\no DHIE: Amanda Moylan, Tim Mahoney\n• Final briefing to discuss council’s recommendation: 8 May 2024\no Panel members: Chris Wilson, David Brown, Grant Christmas,\nJuliet Grant, Tina Christy\no Council assessment staff: Pier Panozzo, Anne Starr, Mark\nAdamson, April Wilkinson\no Applicant representatives: Angelo Di Martino (ADM Architects),\nHarrison Taranto & Daniel Hodge (representing client group -\nEsplanade Wollongong), Luke Rollinson (MMJ Planning)\no Applicant representatives: Amanda Moylan, Tracey Gillet, Tim\nMahoney\n• Final briefing to discuss council’s recommendation: 25 September\n2024\no Panel members: Chris Wilson, Grant Christmas, Natasha Harras\no Council assessment staff: Pier Panozzo, Anne Starr, Mark\nAdamson, April Wilkinson, Martin Jameson\no Applicant representatives: Angelo Di Martino (ADM Architects),\nPeter Taranto (representing client group - Esplanade\nWollongong), Luke Rollinson (MMJ Planning)\no Applicant representatives: Tim Mahoney, Tracey Gillet","stage":"general","stage_basis":"heading","page":7},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Refusal","stage":"general","stage_basis":"heading","page":8},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Draft conditions provided by Council included in Schedule 2","text":"DRAFT CONDITIONS OF CONSENT DA-2022/714 37-39 Burelli Street Wollongong\nAs requested by SRPP 25 September 2024\nConsent has been granted subject to the following conditions:\n1. Approved Plans and Supporting Documentation\nDevelopment must be carried out in accordance with the following approved plans and supporting\ndocumentation (stamped by Council), except where the conditions of this consent expressly\nrequire otherwise.\nPlan No Revision\nNo Plan Title Drawn By Dated\nA-101a A Basement 02 Floor Plan ADM Architects 27 October\n2023\nA102 C Basement 01 Floor Plan ADM Architects 27 October\n2023\nA-103 E Ground Floor Plan ADM Architects 26 June 2024\nA-104 D Level 01 Floor Plan ADM Architects 8 April 2024\nA-105 D Level 02 Floor Plan ADM Architects 8 April 2024\nA-106 D Level 03 Floor Plan ADM Architects 8 April 2024\nA-107 D Level 4-10 Floor Plan ADM Architects 8 April 2024\nA-108 D Level 11 Floor Plan ADM Architects 8 April 2024\nA-109 D Level 12-13 Floor Plan ADM Architects 8 April 2024\nA-201 E North Elevation ADM Architects 27 October\n2023\nA-202 E East Elevation ADM Architects 27 October\n2023\nA-203 D South Elevation ADM Architects 27 October\n2023\nA-204 D West Elevation ADM Architects 27 October\n2023\nA-205 D Section A-A ADM Architects 27 October\n2023\nA-206 B Interface Sections ADM Architects 27 October\n2023\nA-208 B Façade Design Section ADM Architects 27 October\n2023\nSCHEDULE 2\n2 A-209 B Part Sections 01 ADM Architects 27 October\n2023\nA-211 B Part Sections 02 ADM Architects 30 August\n2024\nA-212 A Part Sections 03 ADM Architects 27 October\n2023\nC900 F Waste Management Plan JN Responsive\nEngineering 25 June 2024\n4427-F100\nSheet 1 C Cover Page dsb Landscape\nArchitects\n20 January\n2023\n4427-F101\nSheet 2 E Landscape Plan Ground\nFloor\ndsb Landscape\nArchitects\n26 October\n2023\n4427-F102 D\nSheet 3 D Landscape Plan Third\nFloor\ndsb Landscape\nArchitects\n25 October\n2023\nReport Reference Report Title Prepared By Dated\n610.30718-R01\nversion v2.0\nQualitative Wind\nStatement\nSLR June 2022\n2112009T-R Noise Intrusion\nAssessment\nHarwood\nAcoustics 14 June 2022\nIn the event of any inconsistency between the approved plans and the supporting documentation,\nthe approved plans prevail. In the event of any inconsistency between the approved plans and a\ncondition of this consent, the condition prevails.\nNote: An inconsistency occurs between an approved plan and supporting documentation or\nbetween an approved plan and a condition when it is not possible to comply with both at the\nrelevant time.\nReason:\nTo ensure all parties are aware of the approved plans and supporting documentation.","stage":"general","stage_basis":"heading","page":8},{"label":"11","code":null,"number":"11","title":"","text":"Reason:\nTo comply with Council’s policies and procedures.\n26. Wind Mitigation Measures\nPrior to the issue of the Construction Certificate a final Quantitative Wind Assessment utilising\nWind Tunnel Testing or Computational Fluid Dynamics (CFD) is to be submitted to Council for\napproval, demonstrating that the development will achieve appropri ate wind comfort levels and\nthat all required mitigation measures have been incorporated into the design.\nReason:\nTo comply with Council’s policies and procedures.\n27. Electric Vehicle Charging Infrastructure\nThe following Electric Vehicle Infrastructure is to be shown on the Construction Certificate Plans:\na. 100 per cent of resident spaces to be electric vehicle ready, i.e. with appropriate\nelectrical cabling to the parking space;\nb. One residential visitor space accommodating complete electric vehicle charging from day\nof opening;\nc. One non-residential spaces accommodating complete electric vehicle charging from day\nof opening.\nReason:\nTo comply with Council’s policies and procedures.\n28. Car Parking and Access\nThe development shall make provision for the following:\nResidential\n• 77 car parking spaces (including 10 car parking spaces capable of adaption for people\nwith disabilities)\n• 15 residential visitor car parking spaces\n• 5 residential motorcycle parking spaces\n• A minimum of 24 secure (Security Class B) residential bicycle spaces\n• A minimum of 6 residential visitor bicycle spaces (Security Class C)\nCommercial\n• 10 commercial car parking spaces (including 1 car parking space for people with\ndisabilities)\n• 1 commercial motorcycle parking space\n• A minimum of 4 secure (Security Class B) employee bicycle spaces\n• A minimum of 1 commercial visitor bicycle space (Security Class C)\nThis requirement shall be reflected on the Construction Certificate plans.\nReason:\nTo comply with Council's Development Control Plan.\n29. Parking Dimensions\nThe parking dimensions, internal circulation, aisle widths, kerb splay corners, head clearance\nheights, ramp widths and grades of the car parking areas are to be in conformity with the current\nrelevant Australian Standard AS 2890.1, except where amended by other conditions of this\nconsent. Details of such compliance are to be reflected on the Construction Certificate plans.\nReason:\nTo ensure compliance with Australian Standards.\n12\n30. Disabled Person Parking Space Dimensions\nEach disabled person’s parking space must comply with the current relevant Australian Standard\nAS 2890.6 - Off-street parking for people with disabilities. This requirement shall be reflected on\nthe Construction Certificate plans.\nReason:\nTo ensure compliance with Australian Standards.\n31. Designated Loading/Unloading Facility\nThe designated loading/unloading facility must be clearly delineated with appropriate signage\nand/or line marking to ensure the area is kept clear at all times. The designated loading/unloading\nfacility shall be shown on the Construction Certificate plans.\nReason:\nTo comply with Council's Development Control Plan.\n32. Vehicular Flow Signage\nSuitable barriers, line-marking and painted signage delineating vehicular flow movements must be\nprovided within the car parking areas. These details shall be reflected on the Construction\nCertificate plans.\nReason:\nTo comply with Council's Development Control Plan.\n33. Structures Adjacent to Driveway\nAny proposed structures adjacent to the driveway shall comply with the requirements of the current\nrelevant Australian Standard AS 2890.1 (figure 3.2 and 3.3) to provide for adequate pedestrian\nand vehicle sight distance. This includes, but is not limited to, structures such as signs, letterboxes,\nretaining walls, dense planting etc. This requirement shall be reflected on the Construction\nCertificate plans.\nReason:\nTo ensure compliance with Australian Standards.\n34. Bicycle Parking Facilities\nBicycle parking facilities must have adequate weather protection and provide the appropriate level\nof security as required by the current relevant Australian Standard AS2890.3 - Bicycle Parking\nFacilities. This requirement shall be reflected on the Construction Certificate plans.\nReason:\nTo satisfy the requirements of Australian Standards.\n35. Security Roller Shutters for Basement Car Parking Areas\nThe installation of any security roller shutter for the basement car parking area shall not restrict\naccess to any designated visitor car parking space. In the event that the approved visitor car\nparking spaces are located behind any proposed security roll er shutter, an intercom system is\nrequired to be installed to enable visitor access into the basement car parking area. This\nrequirement is to be reflected on the Construction Certificate plans and any supporting\ndocumentation for the endorsement of the Principal Certifier prior to the release of the Construction\nCertificate.\nReason:\nTo comply with Council's Development Control Plan.\n36. Utilities and Services\nBefore the issue of the relevant Construction Certificate, the applicant must submit the following\nwritten evidence of service provider requirements to the certifier:\na. a letter of consent from Endeavour Energy demonstrating that satisfactory arrangements\ncan be made for the installation and supply of electricity.\nb. a response from Sydney Water as to whether the plans proposed to accompany the\napplication for a construction certificate would affect any Sydney Water infrastructure, and\nwhether further requirements need to be met.\n13 c. other relevant utilities or services - that the development as proposed to be carried out is\nsatisfactory to those other service providers, or if it is not, what changes are required to\nmake the development satisfactory to them.\nReason:\nTo ensure relevant utility and service providers' requirements are provided to the certifier.\n37. Glass Reflectivity Index\nThe reflectivity index of the glass used in the external façade of the building shall not exceed 20\nper cent. The details and samples of the glass to be used are to be submitted with the Construction\nCertificate together with written evidence that the reflectivity of the glass is 20 per cent or less.\nReason:\nTo comply with Council's Development Control Plan.\n38. Site Management, Pedestrian and Traffic Management Plan (Where Works are Proposed\nin a Public Road Reserve)\nThe submission of a Site Management, Pedestrian and Traffic Management Plan to the Principal\nCertifier and Council (in the event that Council is not the Principal Certifier) for approval of both\nthe Principal Certifier and Council is required, prior to the issue of the Construction Certificate.\nThis plan shall address what measures will be implemented for the protection of adjoining\nproperties, pedestrian safety and traffic management and shall be in compliance with the\nrequirements of the latest versions of Australian Standard AS 1742: Traffic Control Devices for\nWorks on Roads and the TfNSW Traffic Control at Worksites Manual.\nThis plan is required to maintain public safety, minimise disruption to pedestrian and vehicular\ntraffic within this locality and to protect services, during demolition, excavation and construction\nphases of the development. This plan shall include the following aspects:\na. Proposed ingress and egress points for vehicles to/from the construction site;\nb. proposed protection of pedestrians, adjacent to the construction site;\nc. proposed pedestrian management whilst vehicles are entering/exiting the construction\nsite;\nd. proposed measures to be implemented for the protection of all roads and footpath areas\nsurrounding the construction site from building activities, crossings by heavy equipment,\nplant and materials delivery and static load from cranes, concrete pumps and th e like;\ne. proposed method of loading and unloading excavation machines, building materials\nformwork and the erection of any part of the structure within the site;\nf. proposed areas within the site to be used for the storage of excavated material,\nconstruction materials and waste containers during the construction period;\ng. proposed traffic control measures such as advanced warning signs, barricades, warning\nlights, after hours contact numbers etc are required to be displayed where works are in\nprogress in any road reserve and shall be in accordance the latest versions of the TfNSW\nSpecification - “Traffic Control at Work Sites Manual” and the Australian Standard AS\n1742: “Manual of Uniform Traffic Control Devices” and accompanying field handbooks\n(SAA HB81);\nh. proposed method of support of any excavation, adjacent to adjoining buildings or the road\nreserve. The proposed method of support is to be certified by a Registered Certifier in Civil\nEngineering; and\ni. proposed measures to be implemented, in order to ensure that no soil/excavated material\nis transported on wheels or tracks of vehicles or plant and deposited on the roadway.\nThe traffic control plan endorsed by Council shall be implemented, prior to the commencement of\nany works upon the construction site.","stage":"general","stage_basis":"heading","page":19},{"label":"14","code":null,"number":"14","title":"","text":"Note: Any proposed works or placement of plant and equipment and/or materials within any road\nreserve will require the separate approval of Council, prior to the commencement of such works,\npursuant to the provisions of the Roads Act 1993.\nReason:\nTo ensure compliance with Australian Standards.\n39. Depth and Location of Services\nThe depth and location of all services (i.e. gas, water, sewer, electricity, telephone, traffic lights,\netc) must be ascertained and reflected on the Construction Certificate plans and supporting\ndocumentation.\nReason:\nTo ensure development does not impact services.\n40. Landscaping\nThe submission of a final Landscape Plan will be required in accordance with the requirements of\nWollongong City Council DCP 2009 Chapter E6 and the approved Landscape Plan (i.e. as part of\nthis consent) for the approval by the Principal Certifier, prior to the issue of the Construction\nCertificate.\nReason:\nTo comply with Council's Development Control Plan.\n41. Property Addressing Policy Compliance\nPrior to the issue of any Construction Certificate, the developer must ensure that any site\naddressing complies with Council’s Property Addressing Policy (as amended). Where appropriate,\nthe developer must also lodge a General Property Addressing Request through Online Services\non Council’s Website (https://www.wollongong.nsw.gov.au/book-and- apply/online-services), for\nthe site addressing prior to the issue of the Construction Certificate. Please allow up to 5 business\ndays for a reply. Enquiries regarding property addressing may be made by calling (02) 4227 8660.\nReason:\nTo comply with Council Policy.\n42. Dilapidation Report\nBefore the issue of a Construction Certificate, a suitably qualified engineer must prepare a\ndilapidation report detailing the structural condition of adjoining buildings, structures or works, and\npublic land, to the satisfaction of the certifier. If the engineer is denied access to any adjoining\nproperties to prepare the dilapidation report, the report must be based on a survey of what can be\nobserved externally and demonstrate, in writing, to the certifier's satisfaction that all reasonable\nsteps were taken to obtain access to the adjoining properties.\nReason:\nTo establish and document the structural condition of adjoining properties and public land for\ncomparison as site work progresses and is completed and ensure neighbours and Council are\nprovided with the dilapidation report.\n43. No Adverse Runoff Impacts on Adjoining Properties\nThe design of the development shall ensure there are no adverse effects to adjoining properties\nor upon the land as a result of flood or stormwater runoff.\nReason:\nTo protect neighbourhood amenity.\n44. External Finishes - Building\nThe building shall be constructed and finished in accordance with the approved schedule of\nfinishing materials and colours except where amended by conditions of this consent. This\nrequirement shall be reflected on the Construction Certificate plans and supporting documentation.\nReason:\nTo ensure all parties are aware of the approved plans and supporting documentation.\n15\n45. Placement of Air Conditioning Units\nAir conditioning systems are not to be located where they are visible from the public streets\nabutting the site. Plans submitted to the Principal Certifier prior to issue of the Construction\nCertificate are to identify any external components of air conditioning systems to ensure they meet\nthe requirements of this condition.\nReason:\nTo protect neighbourhood amenity.\n46. Mechanical Ventilation of the Car Park\nThe car park shall be mechanically ventilated, to be ducted to the roof. Details demonstrating\ncompliance shall be provided with the Construction Certificate.\nReason:\nTo comply with Australian Standards.\n47. External Lighting\nAny lighting of external areas within the development such as the communal open space areas,\ndriveways and car parking entries, shall be designed and located in a manner to prevent light spill\nand/or glare impacts on neighbouring properties. Light placement and design shall be indicated\non the construction certificate drawings.\nReason:\nTo protect neighbourhood amenity.\n48. Adaptable Units\nBefore the issue of a relevant construction certificate, the applicant must ensure a report from a\nsuitably qualified consultant is prepared and demonstrates, to the Certifier's satisfaction, that any\nadaptable dwellings specified in the approved plans or supporting documentation comply with the\nprovisions of AS 4299-1995: Adaptable Housing Standards.\nThe nominated adaptable units within the development must be designed and constructed so as\nto be capable of adaptation for disabled or elderly residents. Dwellings must be designed in\naccordance with the Australian Adaptable Housing Standard (AS 4299-1995), which includes “pre-\nadaptation” design details to ensure visitability is achieved. Level access is required to be provided\nbetween the internal living space and balcony of the adaptable units and sufficient circulation\nspace is required throughout.\nReason:\nTo comply with Australian Standards.\n49. Public Art Consultation\nPublic art is required on the southern and western elevations. The developer is to consult with\nWollongong City Council’s Public Art Advisory Panel and obtain in-principle approval in relation to\nthe proposed public art locations, form and content. Written evidence of consultation and in -\nprinciple approval for the public art is to be provided to the Principal Certifier prior to issue of the\nConstruction Certificate.\nReason:\nTo ensure public art is of a high standard and benefits the community.\n50. Level 3 Communal Open Space\nAmended plans are required to be provided to the Principal Certifier showing rearrangement of\ncommunal open space so that principal areas receive minimum 2 hours of direct sunlight 9am -\n3pm on 21 June in accordance with section 3 -D of the Apartment Design Guide. Principal areas\nare considered to include BBQ, dining area, seating and active spaces.\nReason:\nTo ensure resident amenity and comply with the Apartment Design Guide.\n16\n51. Wind Assessment\nAmended plans are required to be provided to the Principal Certifier implementing measures\ncontained in section ‘’6.1 Wind Mitigation Recommendations’ of the ‘Qualitative Wind Statement’\ndated June 2022 by SLR.\nReason:\nTo ensure resident amenity.\n52. Ventilation\nPlans are to be provided to the Principal Certifier prior to issue of the Construction Certificate\nshowing Units 101, 102, 103, 104, 105, 106, 108, 109, 110, 111, 112, 113, 114, 115 having\noperable louvre highlight windows located above the sliding door and fixed glazing, being a\nminimum height of 1200mm and spanning the width of the apartment.\nReason:\nTo ensure compliance with National Construction Code; to provide adequate amenity to\noccupants; to ensure spaces are ventilated; to ensure indoor air quality levels are controlled to\nacceptable levels; to minimise maintenance and assist in the control of mould and mildew.\n53. Crime Prevention Through Environmental Design (CPTED) - Design Measures\nThe development shall incorporate appropriate design measures to minimise any crime risk to\npatrons or staff and motor vehicles within the car parking areas, including (but not limited to) the\nfollowing:\na. Landscape treatment which allows visibility from the road way and other public areas;\nb. Landscaping at ground level provided which is difficult or uncomfortable to hide in\nor traverse,\nc. Provide clearly marked and sign posted visitor car parking signs (including\nsecurity/intercom system);\nd. Ensure that fire rated doors in the car park have a clear glass panel located no more than\n1.5m from the floor. The panel shall have a minimum dimension of 300mm x 300mm to\nallow visual surveillance within the stairwell and/or next room/space.\nThis requirement shall be reflected on the Construction Certificate plans.\nReason:\nTo comply with Council's Development Control Plan.\n54. Crime Prevention Through Environmental Design (CPTED) - Design Details of Security\nSystem\nThe submission of final design details of proposed security systems to be installed within the\ndevelopment to the Principal Certifier, in order to minimise crime and vandalism related matters is\nrequired, prior to the release of the Construction Certificate.\nReason:\nTo comply with Council's Development Control Plan.\n55. Crime Prevention Through Environmental Design (CPTED) - Design Details of Flood\nLighting Systems\nThe full design details of the proposed floodlighting system and associated light spillage\nmeasures/devices for the development are required to be submitted to the Principal Certifier for\nendorsement, prior to the release of the Construction Certificate. The proposed floodlighting\nsystem and associated light spillage me asures shall be in general accordance with the\nrequirements of Australian Standard AS 4282: Control of the Obtrusive Effects of Outdoor Lighting.\nThe approved light spillage measures shall be installed on the floodlighting system, prior to the\nuse or opera tion of the floodlighting system. The approved light spillage measures shall be\nmaintained at all times.","stage":"general","stage_basis":"heading","page":22},{"label":"17","code":null,"number":"17","title":"","text":"Reason:\nTo ensure compliance with Australian Standards.\nBefore the Commencement of Building Work\n56. Appointment of Principal Certifier\nPrior to commencement of work, the person having the benefit of the Development Consent and\na Construction Certificate must:\na. appoint a Principal Certifier and notify Council in writing of the appointment irrespective\nof whether Council or a Registered Certifier is appointed; and\nb. notify Council in writing of their intention to commence work (at least two [2] days' notice\nis required).\nThe Principal Certifier must determine when inspections and compliance certificates are required.\nReason:\nTo satisfy the requirements of the legislation.\n57. Hazardous Material Survey\nAt least one week prior to demolition, the applicant must prepare a hazardous materials survey of\nthe site and submit to Council a report of the results of the survey. Hazardous materials includes,\nbut are not limited to, asbestos materials, synthetic mine ral fibre, roof dust, PCB materials and\nlead based paint. The report must include at least the following information:\n• the location of hazardous materials throughout the site;\n• a description of the hazardous material;\n• the form in which the hazardous material is found, e.g. AC sheeting, transformers,\ncontaminated soil, roof dust;\n• an estimation (where possible) of the quantity of each particular hazardous material by\nvolume, number, surface area or weight;\n• a brief description of the method for removal, handling, on-site storage and\ntransportation of the hazardous materials, and where appropriate, reference to relevant\nlegislation, standards and guidelines;\n• identification of the disposal sites to which the hazardous materials will be taken.\nThis plan shall be kept on site for the duration of demolition works.\nReason:\nTo comply with Council’s policies and procedures.\n58. Before the Commencement of Building Work - Unexpected Finds Procedure\nThe consent holder must ensure an Unexpected Contaminated Land, Acid Sulfate Soils and\nAsbestos Finds Procedure is prepared and submitted to the Principal Certifier before the\ncommencement of any works. The Unexpected Contaminated Land and Asbestos Finds\nProcedure must be followed should unexpected contaminated land or asbestos (or suspected\ncontaminated land or asbestos) be excavated or otherwise discovered during excavation and\nconstruction. This shall be incorporated into the CEMP.\nReason:\nTo comply with Council’s policies and procedures.\n59. Demolition Works\nThe demolition of the existing structures shall be carried out in accordance with Australian\nStandard AS 2601-2001: The Demolition of Structures or any other subsequent relevant Australian\nStandard and the requirements of SafeWork NSW.\nNo demolition materials shall be burnt or buried on-site. The person responsible for the demolition\nworks shall ensure that all vehicles leaving the site carrying demolition materials have their loads\ncovered and do not track soil or waste materials onto the road. Hazardous and/or intractable\nwastes shall be disposed of to the satisfaction of Council. In the event that the demolition works\nmay involve the obstruction of any road reserve/footpath or other Council owned land, a separate\n18 application shall be made to Council to enclose the public place with a hoarding or fence over the\nfootpath or other Council owned land.\nReason:\nTo comply with Council’s policies and procedures.\n60. Works in Road Reserve - Minor Works\nApproval, under Section 138 of the Roads Act must be obtained from Wollongong City Council’s\nDevelopment Engineering Team prior to any works commencing or any proposed interruption to\npedestrian and/or vehicular traffic within the road reserve caused by th e construction of this\ndevelopment.\nThe application form for Works within the Road Reserve - Section 138 Roads Act can be found\non Council’s website. The form outlines the requirements to be submitted with the application, to\ngive approval to commence works under the Roads Act. It is advised that all applications are\nsubmitted and fees paid, five (5) days prior to the works within the road reserve are intended to\ncommence. The Applicant is responsible for the restoration of all Council assets within the road\nreserve which are impacted by the works/occupation. Restoration must be in accordance with the\nfollowing requirements:\na. All restorations are at the cost of the Applicant and must be undertaken in accordance\nwith Council’s standard document, “Specification for work within Council’s road reserve”.\nb. Any existing damage within the immediate work area or caused as a result of the\nwork/occupation, must also be restored with the final works.\nReason:\nTo satisfy the requirements of the legislation.\n61. Signs On Site\nA sign must be erected in a prominent position on any site on which building work or demolition\nwork is being carried out:\na. showing the name, address and telephone number of the Principal Certifier for the work,\nand\nb. showing the name of the principal contractor (if any) for any building work and a\ntelephone number on which that person may be contacted outside working hours, and\nc. stating that unauthorised entry to the worksite is prohibited.\nAny such sign is to be maintained while the building work or demolition work is being carried out\nbut must be removed when the work has been completed.\nNote: This does not apply in relation to building work or demolition work that is carried out inside\nan existing building that does not affect the external walls of the building.\nReason:\nTo satisfy the requirements of the legislation.\n62. Temporary Toilet/Closet Facilities\nToilet facilities are to be provided at or in the vicinity of the work site on which work involved in the\nerection or demolition of a building is being carried out at the rate of one toilet for every 20 persons\nor part of 20 persons employed at the site.\nEach toilet provided must be:\na. a standard flushing toilet, and\nb. connected to either:\ni. the Sydney Water Corporation Ltd sewerage system or\nii. an accredited sewage management facility or\niii. an approved chemical closet.","stage":"general","stage_basis":"heading","page":25},{"label":"19","code":null,"number":"19","title":"","text":"The toilet facilities shall be provided on-site, prior to the commencement of any works.\nReason:\nTo satisfy the requirements of the legislation.\n63. Structural Engineer's Details\nStructural Engineer’s details for all structurally designed building works such as reinforced\nconcrete footings, reinforced concrete slabs and structural steelwork must be submitted to the\nPrincipal Certifier, prior to the commencement of any works on the site.\nReason:\nTo ensure structural integrity.\n64. Enclosure of the Site\nThe site must be enclosed with a suitable security fence to prohibit unauthorised access, to be\napproved by the Principal Certifier. No building work is to commence until the fence is erected.\nReason:\nTo ensure safety.\n65. Demolition Works\nThe demolition of the existing structures shall be carried out in accordance with Australian\nStandard AS 2601:2001: The Demolition of Structures or any other subsequent relevant Australian\nStandard and the requirements of SafeWork NSW.\nNo demolition materials shall be burnt or buried on-site. The person responsible for the demolition\nworks shall ensure that all vehicles leaving the site carrying demolition materials have their loads\ncovered and do not track soil or waste materials onto the road. Any unforeseen hazardous and/or\nintractable wastes shall be disposed of to the s atisfaction of the Principal Certifier. In the event\nthat the demolition works may involve the obstruction of any road reserve/footpath or other Council\nowned land, a separate application shall be made to Council to enclose the public place with a\nhoarding or fence over the footpath or other Council owned land.\nReason:\nTo satisfy the requirements of the legislation and Australian Standards.\n66. Demolition Notification to Surrounding Residents\nDemolition must not commence unless at least two (2) days written notice has been given to\nadjoining residents of the date on which demolition works will commence.\nReason:\nTo advise neighbourhood.\n67. Consultation with SafeWork NSW - Prior to Asbestos Removal\nA licensed asbestos removalist must give written notice to SafeWork NSW at least five (5) days\nbefore licensed asbestos removal work is commenced.\nReason:\nTo satisfy the requirements of the legislation.\nWhile Building Work is Being Carried Out\n68. Restricted Hours of Construction Work\nThe developer must not carry out any work, other than emergency procedures, to control dust or\nsediment laden runoff outside the normal working hours, namely 7.00 am to 5.00 pm, Monday to\nSaturday, without the prior written consent of the Principal Certifi er and Council. No work is\npermitted on public holidays or Sundays.\nAny request to vary these hours shall be submitted to the Council in writing prior to works being\nundertaken and shall detail:\na. The variation in hours required (length of duration);\nb. the reason for that variation (scope of works);\n20 c. the type of work and machinery to be used;\nd. method of neighbour notification;\ne. supervisor contact number;\nf. any proposed measures required to mitigate the impacts of the works.\nNote: Other legislation, such as the Noise Guide for Local Government January 2023, may control\nthe activities for which Council has granted consent, including but not limited to, the Protection of\nthe Environment Operations Act 1997.\nReason:\nTo ensure protection of the environment and neighbourhood amenity. To mitigate adverse amenity\nimpacts in the locality.\n69. Rock Breaking, Rock Hammering, Sheet Piling, Pile Driving\nRock breaking, rock hammering, sheet piling, pile driving and similar activities may only be carried\nout in accordance with a Demolition and Construction Noise and Vibration Management Plan\nendorsed by the Principal Certifier prior to issue of the Construction Certificate.\nThe Principal Certifier must ensure building work, demolition or vegetation removal is not carried\nout on Sundays and public holidays, except where there is an emergency. Unless otherwise\napproved within a construction site management plan, construction vehicles, machinery, goods or\nmaterials must not be delivered to the site outside the approved hours of site works.\nAny variation to the hours of work requires Council's approval.\nAny request to vary the approved hours shall be submitted to the Council in writing detailing:\na. The variation in hours required (length of duration);\nb. the reason for that variation (scope of works;\nc. the type of work and machinery to be used;\nd. method of neighbour notification;\ne. supervisor contact number; and\nf. any proposed measures required to mitigate the impacts of the works\nThe findings, recommendations and management controls in the Demolition and Construction\nNoise and Vibration Management Plan must be adhered to in full for the duration of the works the\nsubject of the plan.\nFor the duration of the site works, noise and vibration must be managed in accordance with the\napproved Construction Noise and Vibration Management Plan.\nPrior to the commencement of any site works, the Proponent shall undertake a vibration\nassessment to identify all sensitive receivers where vibration limits exceed levels recommended\nby a registered Geotechnical/Structural Engineer with regard to structural damage buildings;\n• German Standard DIN 4150 Part 3 Structural Vibration in Buildings. Effects on\nStructures; and\n• For human exposure to vibration, the evaluation criteria presented in British Standard\nBS 6472- Guide to Evaluate Human. Exposure to Vibration in Buildings (1Hz to 80 Hz)\nfor low probability of adverse comment.\nThe findings and recommendations from the assessment shall be documented in a Vibration\nManagement Plan prepared by a suitably qualified Vibration Consultant/Company and submitted\nto Council for Approval prior to the commencement of any site works. For the duration of the works\nvibration must be managed in accordance with the approved Construction Vibration Management\nPlan.\nThe Management Plans shall include site contact details, policies, procedures for reporting and\nmanaging community specific issues arising from site establishment/excavation/construction\n21 activities and procedures for handling complaints received. This will involve the complaint being\nreferred directly to the principal contractor or a designated person. If the principal contractor is not\non site at the time, an entry in the site Consultation Management Book will be made to ensure\nappropriate action and monitoring is undertaken. A response would be required by the principal\ncontractor to the complainant within 24 hours and the ‘close out’ the complaint. The complaint\nresolution will be recorded in Consultation Manager Book. The Consultation Manager Book will be\nmaintained on site and made available to Council on request. Copies of the Management Plan and\nDilapidation Reports shall be provided to neighbours on requested\nRock breaking, rock hammering, sheet piling, pile driving and similar activities may only be carried\nout between the following hours:\n(a) 7:00am to 12:00pm, Monday to Friday;\n(b) 2:00pm to 6:00pm Monday to Friday; and\n(c) 8:00am to 1:00pm Saturday.\nFor the duration of the site works noise and vibration monitoring and reporting on weekly as\nrecommended in accordance with the approved Construction Noise and Vibration Management\nPlan. A copy of monitoring report need to submit to Councils’ DAC Division referring the DA\nnumber.\nNote: The developer is advised that other legislation may control the activities for which Council\nhas granted consent, including but not limited to, the Protection of the Environment Operations\nAct 1997.\nReason:\nTo mitigate adverse amenity impacts in the locality.\n70. Podium Planting\nAll podium planting areas are to have a waterproofing membrane that can provide a minimum 10\nyear warranty on product. Protective boarding is to be installed to protect membrane from damage.\nAll podium planting areas to be provided with an adequate drainage system connected to the\nstormwater drainage system. The planter box is to be backfilled with free draining planter box soil\nmix.\nIf selected mulch is decorative pebbles/gravel, the maximum gravel pebble size is 10mm diameter.\nReason:\nTo comply with Council’s policies and procedures.\n71. Provision of Taps/Irrigation System\nThe provision of common taps and/or an irrigation system is required to guarantee that all\nlandscape works are adequately watered. The location of common taps and/or irrigation system\nmust be implemented in accordance with the approved Landscape Plan.\nReason:\nTo comply with Council’s policies and procedures.\n72. Mailboxes and Street Numbering\nThe developer must install mailboxes in accordance with Australia Post Guidelines and Clause\n4.5.2 of Chapter D13 of Wollongong Development Control Plan 2009. The mailboxes must be\nprovided in one accessible location adjacent to the main entrance to the development, integrated\ninto a wall if possible and constructed of materials consistent with th e appearance of the building.\nLetterboxes shall be secure and large enough to accommodate articles such as newspapers,\nparcels and the like. Prominent house numbers are to be displayed, with a minimum number size\nof 150 mm in height for each number and letter in the alphabet.\nProminent house numbers are to be displayed, with a minimum number size of 150 mm in height\nfor each number and letter in the alphabet. The developer must install minimum two (2) reflective\npaint house number on face of kerb along street frontage of the pr operty to assist emergency\nservices/deliveries/visitors.","stage":"general","stage_basis":"heading","page":27},{"label":"22","code":null,"number":"22","title":"","text":"Reason:\nTo identify the property.\n73. Demolition Materials - Disposal\nAll demolition materials not being reused on-site shall be disposed of only at a recycling or waste\nmanagement facility that may lawfully receive that waste.\nReason:\nTo comply with Council’s policies and procedures.\n74. Waste Classification and Disposal of Contaminated Soil and Material(s), Solid and Liquid\n1. All soils and material(s), liquid and solid, to be removed from the site must be analysed\nand classified by an appropriately qualified and experienced environmental consultant, in\naccordance with the Protection of the Environment (Waste) Regulation 2014 and related\nguidelines, in particular NSW EPA Waste Classification Guidelines (2014), prior to off-site\ndisposal.\n2. The waste classification report, including the results of testing, must be compiled, or\nreviewed and approved by an appropriately qualified and certified consultant, and must\nbe submitted to and approved by Council before off -site disposal. The front cover of the\nreport must include the details of the consultant’s certification. A certified contaminated\nland consultant is a contaminated land consultant certified under either:\no the Environment Institute of Australia and New Zealand’s (EIANZ) Certified\nEnvironmental Practitioner (Site Contamination) (CEnvP(SC)) scheme; or\no the Soil Science Australia (SSA) Certified Professional Soil Scientist\nContaminated Site Assessment and Management (CPSS CSAM) scheme.\n3. All waste material(s) must be disposed of at an appropriately licensed waste facility for the\nspecific waste.\n4. Receipts for the disposal of the waste must be submitted to council within 14 days of the\nwaste being disposed.\n5. All waste must be transported by a contractor licenced to transport the specific waste, and\nin vehicles capable of carting the waste without spillage, and meeting relevant\nrequirements and standards. All loads must be covered prior to vehicles leaving the site.\nReason:\nTo comply with Council’s policies and procedures.\n75. Excess Excavated Material - Disposal\nExcess excavated material shall be classified according to the NSW Environment Protection\nAuthority’s Waste Classification Guidelines - Part 1: Classifying Waste (2014) prior to being\ntransported from the site and shall be disposed of only at a location th at may lawfully receive that\nwaste.\nReason:\nTo comply with Council’s policies and procedures.\n76. Dust Suppression Measures\nActivities occurring during the demolition, excavation and construction phases of the development\nmust be carried out in a manner that will minimise the generation of dust. All surfaces intended to\ncarry vehicular traffic must be managed with the aim of preventing windblown dust emissions.\nReason:\nTo comply with Council’s policies and procedures.\n77. Discharge of Accumulated Water\nAny water accumulating in excavations on-site or in the settlement ponds shall not be discharged\nto Council’s stormwater system, unless all the following criteria are met:\na. The concentration of suspended solids in the water to be discharged does not exceed 50\nmg/L; and\nb. The turbidity of the water to be discharged does not exceed 50 NTUs/FTUs; and\n23 c. The pH of the water to be discharged is between 6.5 and 8.5; and\nd. The water to be discharged contains no visible oil or grease; and\ne. If alum has been used to reduce suspended solids, the concentration of aluminium in the\nwater to be discharged does not exceed 0.055 mg/L; and\nf. The water to be discharged does not contain any substances known to be toxic to aquatic\nlife; and\ng. The flow rate of discharged water does not exceed 55 litres per second in dry weather\nconditions, or is less than the capacity of the receiving stormwater drain; and\nh. A copy from a NATA accredited laboratory of sample test results for suspended solids and\npH (and aluminium if applicable) confirming the water to be discharged meets criteria 1\nand 2 (and criteria 4 if applicable) as stated above is submitted to Council’s Environment\nPlanning Team (phone 4227 7111; fax 4227 7277; email\nrecords@wollongong.nsw.gov.au, attention Environment Planning Team Manager); and\ni. Written permission is obtained from Council’s Environment Planning Team prior to any\ndischarge.\nAlternatively, such waters are to be removed by tanker for disposal at a NSW Environment\nProtection Authority licensed waste facility.\nReason:\nTo comply with Council’s policies and procedures.\n78. While Building Work is Being Carried Out - Unexpected Finds Procedure\nThe consent holder must ensure the Unexpected Contaminated Land, Acid Sulfate Soils and\nAsbestos Finds Procedure is implemented throughout the excavation and construction phases of\nthe development.\nReason:\nTo comply with Council’s policies and procedures.\n79. Protection of Public Places\nIf the work involved in the erection or demolition of a building involves the enclosure of a public\nplace or is likely to cause pedestrian/vehicular traffic in a public place to be obstructed or rendered\ninconvenient, or have the potential for conflict between pedestrians and vehicles:\na. A hoarding or fence must be erected between the work site and the public place;\nb. an awning is to be erected, sufficient to prevent any substance from, or in connection with,\nthe work falling into the public place;\nc. the work site must be kept lit between sunset and sunrise if it is likely to be hazardous to\npersons in a public place;\nd. safe pedestrian access must be maintained at all times;\ne. any such hoarding, fence or awning is to be removed when the work has been\ncompleted. Reason:\nTo comply with Council's requirements.\n80. Lighting not to cause Nuisance\nThe lighting of the premises must be directed so as not to cause nuisance to the owners or\noccupiers of adjoining premises or to motorists on adjoining or nearby roads.\nReason:\nTo protect neighbourhood amenity.\n24\n81. Building Operations Not to Discharge Pollutants\nBuilding operations such as brick cutting, the washing of tools or paint brushes, or other equipment\nand the mixing of mortar must not be carried out on the roadway or public footpath or any other\nlocations which could lead to the discharge of materials into the stormwater drainage system or\nnatural watercourse.\nReason:\nTo ensure ongoing protection of the environment and neighbourhood amenity.\n82. Excavation Protection and Notification\nIf an excavation associated with the erection or demolition of a building extends below the level of\nthe base of the footings of a building on adjoining allotment of land, the person causing the\nexcavation to be made:\na. Must preserve and protect the adjoining building from damage; and\nb. if necessary, must underpin and support the building in an approved manner; and\nc. must, at least seven (7) days before excavation below the level of the base of the footings\nof a building on an adjoining allotment of land, give notice of intention to do so to the owner\nof the adjoining allotment of land and furnish particulars of the excavation.\nReason:\nTo ensure compliance with relevant Standards.\n83. Safe Excavations and Backfilling\nAll excavations and backfilling associated with the erection of a building must be executed safely\nand in accordance with appropriate professional standards.\nReason:\nTo ensure compliance with relevant Standards.\n84. Guarding of Excavations and Backfilling\nAll excavations and backfilling associated with the erection of a building must be properly guarded\nand protected to prevent them from being dangerous to life or property.\nReason:\nTo ensure compliance with relevant Standards.\n85. Asbestos Removal by a Licensed Asbestos Removalist\nThe removal of any asbestos material must be carried out by a licensed asbestos removalist if\nover 10 square metres in area of non -friable asbestos, or if any type of friable asbestos in strict\naccordance with SafeWork NSW requirements (https://www.safework.nsw.gov.au).\nReason:\nTo satisfy the requirements of the legislation.\n86. Asbestos Clearance Certificate\nThe internal floor area affected or likely to be affected, by scattering of asbestos pieces, particles\nor fibres during demolition or cutting into the building, is to be cleaned by vacuuming by a contractor\napproved by SafeWork NSW. A Clearance Certificate to certify that the site area is free of asbestos\nis to be submitted to Council by a licensed asbestos assessor within 14 days of the completion of\nrenovations (or prior to the Occupation Certificate being issued).\nReason:\nTo satisfy the requirements of the legislation.\n87. Asbestos Waste Collection, Transportation and Disposal\nAsbestos waste must be prepared, contained, transported and disposed of in accordance with\nSafeWork NSW and NSW Environment Protection Authority requirements. Asbestos waste must\nonly be disposed of at a landfill site that can lawfully receive this this type of waste. A receipt must\nbe retained and submitted to the Principal Certifier, and a copy submitted to Council (in the event\nthat Council is not the Principal Certifier), prior to commencement of the constructi on works.","stage":"general","stage_basis":"heading","page":30},{"label":"25","code":null,"number":"25","title":"","text":"Reason:\nTo satisfy the requirements of the legislation.\n88. Acid Sulfate Soils\nThe Wollongong Local Environmental Plan 2009 Acid Sulfate Soils Map has identified that this\nproperty may be affected by classes 3, 4 or 5 Acid Sulfate Soils. Acid Sulfate Soils contain iron\nsulfides which, when exposed to air due to drainage or disturbance, may produce sulfuric acid and\nrelease toxic quantities of iron, aluminium and heavy metals. The Acid Sulfate Soils Map is an\nindication only and you are advised that you may encounter Acid Sulfate Soils during the\nexcavation for the proposed development.\nAny spoil material extracted or excavated from the foundations must be neutralised with\ncommercial lime (calcium bicarbonate) by the addition of 10 kilograms of lime per 1 cubic metre of\nspoil material before it is disposed of or re-used on-site. Lime is to be added by evenly distributing\nover all exposed surface areas, drilled piers and footing trenches on the site, prior to pouring\nconcrete.\nCouncil suggests the applicant refer to the Acid Sulfate Soils Assessment Guidelines contained in\nthe Acid Sulfate Soils Manual, prepared by NSW Acid Sulfate Management Advisory Committee,\nAugust 1998 for further information.\nReason:\nTo satisfy the requirements of the legislation.\n89. External Plant and Equipment\nExternal plant and equipment such as air conditioners, compressors and other machinery likely to\nemit noise shall be located so adjoining areas are not adversely affected.\nReason:\nTo ensure ongoing protection of the environment and neighbourhood amenity.\n90. Implementation of BASIX Commitments\nWhile building work is being carried out, the applicant must undertake the development strictly in\naccordance with the commitments listed in the BASIX certificate(s) approved by this consent, for\nthe development to which the consent applies.\nReason:\nTo satisfy the requirements of the legislation.\n91. Responsibility for Changes to Public Infrastructure\nWhile building work is being carried out, the applicant must pay any costs incurred as a result of\nthe approved removal, relocation or reconstruction of infrastructure (including ramps, footpaths,\nkerbs and gutter, light poles, kerb inlet pits, service pro vider pits, street trees or any other\ninfrastructure in the street footpath area).\nReason:\nTo ensure payment of approved changes to public infrastructure.\n92. Unexpected Archaeological Finds\nShould an unexpected find be identified during ground disturbing works, work should cease, and\nthe area be cordoned off to prevent any further disturbance. The applicant should engage an\narchaeologist to assess the condition and significance of the find. Should the find be determined\nto be of heritage significance (local or State), the Heritage Council should be notified under s.146\nof the NSW Heritage Act 1977. Depending on the nature of the discovery, additional assessment\nand possibly an excavation permit may be required prior to the recommencement of excavation in\nthe affected area.\nWorks are not to recommence until advised in writing by Heritage NSW or Council’s Heritage Staff.\nReason:\nTo satisfy the requirements of the legislation.","stage":"general","stage_basis":"heading","page":33},{"label":"26","code":null,"number":"26","title":"Before the Issue of an Occupation Certificate","text":"93. Completion of Landscape Works on Council Owned or Controlled Land\nThe Developer must complete all landscape works required within Council’s road reserve, or other\nCouncil owned or controlled land, in accordance with the conditions of this consent. The total cost\nof all such landscape works shall be fully borne by the Developer and any damage to Council’s\nassets shall be the subject of restoration works sufficient to restore the asset to its previous state\nand configuration previous to the commencement of work s. Evidence that this requirement has\nbeen met must be satisfied prior to the issue of the Occupation Certificate.\nReason:\nTo comply with Council’s policies and procedures.\n94. Acoustic Design Compliance Report\nA final acoustic design compliance report confirming compliance with the acoustic report prepared\nby Traffic Noise Intrusion Assessment prepared by Harwood Acoustics and dated 14 June 2022\nshall be prepared by a suitably qualified and experienced acoustic engineer (who is a member of\neither the Australian Acoustical Society or the Association of Australasian Acoustical Consultants)\nand submitted to the Certifying Authority for approval prior to the release of the Occupation\nCertificate.\nReason:\nTo comply with Council’s policies and procedures.\n95. Site Contamination Validation Report and Site Contamination Audit Statement\nThe submission of a site contamination validation report to the Principal Certifier and Council (in\nthe event that Council is not the Principal Certifier for its records) for approval is required, prior to\nthe issue of an Occupation Certificate. This validation report shall verify that:\na. all site contamination remediation works have been satisfactorily completed;\nb. the site is not affected by any soil strata and/or groundwater table contamination, above\nNSW EPA threshold limit criteria; and\nc. the site is rendered suitable for the proposed development.\nThe submission of a site audit statement/final clearance certificate is also required from an\naccredited auditor pursuant to the provisions of Part 4 of the Contaminated Land Management Act\n1997 confirming that the site has been satisfactorily remediated and is suitable for the proposed\ndevelopment.\nReason:\nTo comply with Council’s policies and procedures.\n96. BASIX\nAn Occupation Certificate must not be issued unless accompanied by the BASIX Certificate\napplicable to the development. The Principal Certifier must not issue the Occupation Certificate\nunless satisfied that selected commitments have been complied with as specified in the relevant\nBASIX Certificate.\nNOTE: Clause 44 of the Environmental Planning and Assessment (Development Certification and\nFire Safety) Regulation 2021 provides for independent verification of compliance in relation to\ncertain BASIX commitments.\nReason:\nTo satisfy the requirements of the legislation.\n97. Completion of Landscape and Tree Works\nBefore the issue of an Occupation Certificate, the Principal Certifier must be satisfied that all\nlandscape and tree works, including pruning in accordance with AS 4373-2007 Pruning of amenity\ntrees and the removal of all noxious weed species, have been completed in accordance with the\napproved plans and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"text-under-general-heading","page":34},{"label":"27","code":null,"number":"27","title":"","text":"Reason:\nTo ensure the approved landscaping works have been completed in accordance with the approved\nlandscaping plan(s).\n98. Arborist Verification - Street Tree Installation\nPrior to the issue of Occupation Certificate, the developer must supply certification in the form of\na report, including photographic evidence, from an AQF Level 5 Arborist to the Principal Certifier\nand Wollongong City Council to verify:\na. The tree stock complies with AS 2203:2018 Tree Stock for Landscape Use.\nb. The tree pits have been constructed and the trees installed in accordance with the\nrequirements of the Wollongong City Council City Centre Public Domain Technical Manual\nand arboricultural best practice.\nReason:\nTo comply with the Australian Standards.\n99. Risk and Emergency Management Plan\nPrior to the issue of an Occupation Certificate, a Risk and Emergency Management Plan that\ncomplies with Australian Standards 3745 (2010), or 1851 (2012) shall be provided to the Principal\nCertifier.\nReason:\nTo comply with Australian Standards.\n100. Public Art Completion\nPrior to issue of the Occupation Certificate, the approved public art shall be completed to the\nsatisfaction of the Wollongong Public Art Advisory Panel. Evidence of the Panel’s written\nsatisfaction shall be provided to the Principal Certifier.\nReason:\nTo ensure public art is of a high standard and benefits the community.\n101. Dilapidation Report\nBefore the issue of an Occupation Certificate, a suitably qualified engineer must prepare a\ndilapidation report detailing the structural condition of adjoining buildings, structures or works, and\npublic land, to the satisfaction of the certifier.\nReason:\nTo establish and document the structural condition of adjoining properties and public land for\ncomparison as site work progresses and is completed and ensure neighbours and Council are\nprovided with the dilapidation report.","stage":"general","stage_basis":"heading","page":35},{"label":"28","code":null,"number":"28","title":"","text":"Reason:\nTo comply with Council’s Development Control Plan.\n104. On-site Waste Collection Only\nAll waste collection must be carried out from within the site. Waste collection from the street is not\npermitted at any time.\nReason:\nTo comply with Council's Development Control Plan.\n105. Clothes Drying on Balconies/Terrace Areas Prohibited\nThe use of the balconies/terrace areas for the external drying of clothes is strictly prohibited.\nReason:\nTo ensure protection of the neighbourhood amenity.\n106. Street Tree Establishment Period - City Centre/Commercial Village Centre\nThe Developer must comply with the terms of an approved landscape maintenance program for a\nminimum period of 12 months to ensure that all landscape works within Council’s road reserve or\nCouncil owned or controlled land becomes well established by regular maintenance. The Street\nTree Establishment Period shall commence from the issue of the Occupation Certificate.\nThe program must include the following elements: watering, weeding, litter removal, mulching,\nfertilising, tree guard and grate maintenance, and pest and disease control.\nDetails of the proposed program must be submitted with the Landscape Plan to the Principal\nCertifier for approval prior to release of the Construction Certificate.\nReason:\nTo comply with Council's Development Control Plan.\n107. Graffiti Removal\nAny graffiti shall be removed immediately from the exterior of the building or any associated\nstructures including any fences, site services and retaining/planter bed walls.\nReason:\nTo ensure protection of the environment and neighbourhood amenity.\n108. Public Art\nThe approved public art locations shall contain approved public art in perpetuity, to the satisfaction\nof Wollongong City Council.\nReason:\nTo ensure public art is of a high standard and benefits the community.\n109. Strata Plan Requirements\nShould a Strata Plan be prepared for this development in the future, the following matters must be\naddressed:\na. Garbage and recycling rooms must be contained within the common area;\nb. Motorbike and bicycle storage areas and visitor car parking must be contained within the\ncommon area; and\nc. Appropriate allocation of carparking and storage areas to the dwellings.\nReason:\nTo ensure protection of the environment and neighbourhood amenity.\n110. Residential Storage\nEach residential unit shall be allocated storage within the residential storage area provided within\nthe building. The residential storage area shall be appropriately secured and fitted with CCTV\nsurveillance. This requirement shall be reflected on the Construction Certificate plans.\nThe use of the balconies/terrace areas for the external drying of clothes is strictly prohibited.","stage":"ongoing","stage_basis":"heading","page":36},{"label":"29","code":null,"number":"29","title":"","text":"Reason:\nTo ensure protection of the environment and neighbourhood amenity.\nReasons\nThe reasons for the imposition of the conditions are:\n1. To minimise any likely adverse environmental impact of the proposed development.\n2. To ensure the protection of the amenity and character of land adjoining and in the locality.\n3. To ensure the proposed development complies with the provisions of Environmental Planning\nInstruments and Council’s Codes and Policies.\n4. To ensure the development does not conflict with the public interest.","stage":"ongoing","stage_basis":"heading","page":37}]});
